INSERT INTO itinerary_revisions (id, itinerary_id, version_number, parent_revision_id, milestone_label, change_summary, save_type, snapshot, snapshot_checksum, created_at) VALUES ('7629f9b2-af36-99bc-ecdc-5674f84fe232', 'f793d115-3003-33f1-ffae-310170658f5e', 1, NULL, 'Imported package content', 'Imported from 09 Days Rajasthan Tour for Website - Updated.docx', 'manual'::revision_save_type, '{"header": {"title": "09 Days Udaipur-Mount Abu-Jodhpur-Jaisalmer- Bikaner Tour Package", "subtitle": "Udaipur-Mount Abu-Jodhpur-Jaisalmer- Bikaner", "tour_code": "DR060", "duration_label": "08 Night / 09 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "45f6a4cb-28a1-cfa5-566e-b7ec1099f037", "day_number": 1, "day_title": "Arrival in Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Udaipur also known as the \"City of Lakes,\" it enchants with its serene waters, grand palaces, and romantic atmosphere. Visit the exquisite City Palace and enjoy a boat ride on Lake Pichola.\nUpon arrival at Udaipur Railway Station/Airport, our representative will warmly greet you and transfer you to your hotel. Spend the rest of the day relaxing at your hotel.\nIn the evening, we will visit Pichola lake.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "88bc8aa7-bb49-9cab-7c5a-47c44394a914", "day_number": 2, "day_title": "Udaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore the enchanting Lake City:\nCity Palace - Regal splendor by the lake.\nJagdish Temple - Spiritual oasis in marble.\nBhartiya Lok Kala Mandal - Symbol of cultural vibrancy.\nPratap Smarak - Monument to valorous spirit.\nShilp Gram - A village of creativity.\nBagori ki Haveli - Legacy of Udaipur.\nSaheliyon ki Bari - Garden of royal friendships.\nOvernight stay at your hotel in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "c21b5bbd-8d48-58ed-835f-f6bd6869289a", "day_number": 3, "day_title": "Udaipur – Mount Abu Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Mount Abu is Rajasthan''s only hill station, Mount Abu offers a refreshing retreat with cool climate, lush greenery, and scenic viewpoints. Visit the famous Dilwara Temples and enjoy the peaceful Nakki Lake.\nAfter breakfast, depart for Mount Abu. Check-in at the hotel and explore the highlights:\nDelwara Temple– Architectural marvel of marble.\nVedi Temple - Sanctuary of divine tranquility.\nNakki Lake - Mirror of Mount Abu''s charm.\nSunset Point - Dusk paints the horizon.\nTod Rock - Witness to ancient tales.\nGuru Shikhar - Peak of spiritual heights.\nAchalgarh Mahadev - Ancient fortresses of faith.\nBrahma Kumari Ashram - Sanctuary of spiritual wisdom.\nOvernight stay at Mount Abu hotel.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "60179312-d5aa-7362-3b17-bb95710ee987", "day_number": 4, "day_title": "Mount Abu - Ranakpur - Jodhpur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "The \"Blue City\" Jodhpur boasts the majestic fort and a sea of blue houses. Discover its rich history, exciting shopping markets, and scenic views of the Thar Desert.\nAfter breakfast, journey to Jodhpur via Ranakpur Jain Temples, renowned for their majestic architecture. Upon arrival in Jodhpur, check-in at the hotel.\nOvernight stay at your hotel in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "26294044-3434-c94f-9410-aaf4bda38d08", "day_number": 5, "day_title": "Jodhpur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore the Blue City''s landmarks:\nUmaid Bhawan Palace Museum– Palace of royal grandeur.\nJaswant Thada - Memorial in marble grace.\nMehrangarh Fort - Fortress of history''s symbol.\nOvernight stay at your hotel in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jodhpur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "81fec54f-2cf6-dd14-9bf3-0e5c32dd9d92", "day_number": 6, "day_title": "Jodhpur - Jaisalmer", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, travel to Jaisalmer. Check-in at the hotel and visit the Golden City''s attractions:\nWar Museum– Stories of bravery.\nGadisar Lake - Tranquil oasis in the desert.\nVyas Chhatri - Carved in golden sandstone.\nOvernight stay at your hotel in Jaisalmer.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "284dc7f5-ab0d-155e-f944-3756d77539de", "sort_order": 0, "title": "Jaisalmer", "description": "The \"Golden City\" Jaisalmer mesmerizes with its yellow sandstone architecture and the magnificent Jaisalmer Fort. Experience desert safaris, ornate havelis, and a glimpse into desert life.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "38437add-318e-1c8a-e261-b73e85d9ee40", "day_number": 7, "day_title": "Sightseeing & Jaisalmer Desert", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore Jaisalmer''s wonders:\nJaisalmer Fort & Palaces - Legends in sandstone citadel.\nJain Temples - Architectural gems of faith.\nPatwon ki Haveli - Merchant opulence in stone.\nSalim Singh ki Haveli - Legacy of noble heritage.\nNathmal ki Haveli - Artistry in desert architecture.\nLater, enjoy a unique desert experience with an overnight stay in tents at the sand dunes, complete with cultural programs, camel rides, bonfires, sunset views, and dinner.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "18a39168-f725-b640-3789-0c6a6d5de167", "day_number": 8, "day_title": "Jaisalmer - Bikaner", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, depart for Bikaner. Check-in at the hotel and explore Bikaner''s attractions:\nCamel Breeding Farm - Hub of desert life.\nJunagarh Fort - Legacy of Bikaner''s strength.\nKarni Mata Temple–A holy place.\nOvernight stay at your hotel in Bikaner.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "86ce42c3-c5ca-9fde-3833-fd3f4f8b821d", "day_number": 9, "day_title": "Bikaner - Jaisalmer Departure", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, return to Jaisalmer for departure. Our representative will drop you at Jaisalmer Railway Station or Airport. (The Tour Ends)", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_categor